import { useMemo } from 'react';

import { featureToggles } from 'config/featureToggle';
import { useFeatureToggle } from 'hooks';

export const useConnectionsCreativityHomeContentToggle = () => {
  const [isEnabled, isLoading] = useFeatureToggle(
    featureToggles.pillar.connectionsAndCreativity
      .connections_creativity_home_content,
  );

  const isContentEnabled = useMemo(
    () => isEnabled === true && !isLoading,
    [isEnabled, isLoading],
  );

  return {
    isContentEnabled,
    isLoading,
  };
};
